def link(z, b, k):
    if k == 'cubic':
        return z - b * z ** 3
    if k == 'tanh':
        return np.tanh(b * z) / b
    if k == 'atan':
        return np.arctan(b * z) / b
    if k == 'root':
        return z / np.sqrt(1 + b * z * z)
    if k == 'rational':
        return z / (1 + b * z * z)
    if k == 'sinh_inverse':
        return np.arcsinh(b * z) / b
    if k == 'erf':
        from scipy.special import erf
        return erf(b * z) * np.sqrt(np.pi) / (2 * b)

def features(x, j, b, k, terms):
    z = x[:, j]
    other = [i for i in range(4) if i != j]
    a = [np.ones(len(x)), link(z, b, k), *x[:, other].T]
    if terms == 'adj':
        a.extend(x[:, other].T ** 2)
    if terms == 'diag2':
        a.extend(x.T ** 2)
    if terms == 'full2':
        a.extend((x[:, i] * x[:, l] for i in range(4) for l in range(i, 4)))
    return np.column_stack(a)

def fit(x, y, k, terms):
    from scipy.optimize import least_squares
    model = []
    for j in range(4):
        A = features(x, j, 0.55, k, terms)
        p = np.r_[0.55, np.linalg.lstsq(A, y[:, j], rcond=None)[0]]

        def residual(p):
            return features(x, j, p[0], k, terms) @ p[1:] - y[:, j]
        for (scale, loss) in [(0.12, 'soft_l1'), (0.025, 'cauchy'), (0.008, 'cauchy')]:
            p = least_squares(residual, p, bounds=(np.r_[0.0001, np.full(len(p) - 1, -np.inf)], np.r_[4.0, np.full(len(p) - 1, np.inf)]), loss=loss, f_scale=scale, max_nfev=100).x
        model.append(p)
    return model

def terms(t, q, k):
    u = q[0] * t
    a = np.tanh(u)
    v = q[-1] * t
    extra = {'cubic': [t ** 3], 'cubrat': [t ** 3 / (1 + v * v)], 'rat': [t / (1 + v * v)], 'sin': [np.sin(v)], 'atan': [np.arctan(v)], 'sqrt': [v / np.sqrt(1 + v * v)], 'softsign': [t / (1 + abs(v))], 'damped': [t * np.exp(-v * v)], 'ratlin': [t, t / (1 + v * v)], 'sinlin': [t, np.sin(v)], 'positive_tail': [t, t ** 3 / (1 + v * v)]}[k]
    return np.column_stack([np.ones_like(t), a, *extra])

def _fit(samples, dt, times, strain, rate):
    from scipy.optimize import least_squares
    y = np.concatenate((strain.ravel(), rate))
    n_curve = strain.size
    bounds = (np.r_[np.log([0.05000001, 0.05000001]), [-np.inf] * 7], np.r_[np.log([24.999999, 24.999999]), [np.inf] * 7])

    def matrix(u):
        (cur, slope) = _design(u, samples, dt, times)
        return np.vstack((cur.reshape(-1, 7), slope))
    grid = np.geomspace(0.085, 20.0, 12)
    best = float('inf')
    for (i, fast) in enumerate(grid[:-1]):
        for slow in grid[i + 1:]:
            u = np.log([fast, slow])
            a = matrix(u)
            theta = np.linalg.lstsq(a, y, rcond=None)[0]
            err = a @ theta - y
            cost = np.mean(np.minimum(err[:n_curve] ** 2, 0.25 ** 2))
            cost += np.mean(np.minimum(err[n_curve:] ** 2, 0.25 ** 2))
            if cost < best:
                (best, p) = (cost, np.r_[u, theta])

    def refine(p, scale, loss, f_scale):

        def residual(q):
